"""LIBERO pilot action planning through the existing joint planner owner."""
from __future__ import annotations

import numpy as np

from task_env.planners.joint import JointPositionPlanner, JointPositionPlannerConfig


def build_planner(task_input: dict) -> dict:
    native = task_input["native_reference"]["planner"]
    return {
        "native_reference": native,
        "core_candidate": task_input["requested_core_candidate"]["planner"],
        "status": "bounded joint-space plan generated by task_env.planners.joint; no IK/collision claim",
        "current_owners": ["task_env/planners/joint.py"],
        "action_contract": "seven absolute joint radians plus normalized gripper mapped to aggregate opening meters",
    }


def plan_episode_actions(observation: dict, *, row_index: int, steps: int) -> np.ndarray:
    """Plan a small bounded arm move and hand closure from public reset state.

    The returned final component follows the existing Planner's normalized
    gripper convention.  The worker converts it to the selected Core action's
    aggregate opening in metres before calling ``SelectedReferenceEnv.step``.
    """
    if type(row_index) is not int or row_index not in (0, 1, 2):
        raise ValueError("D01 pilot planner admits only source rows 0, 1, and 2")
    if type(steps) is not int or not 1 <= steps <= 64:
        raise ValueError("D01 planner step count must be in [1,64]")
    try:
        current = np.asarray(observation["state"]["joint_position"], dtype=np.float64)
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError("planner requires public SelectedReferenceEnv joint_position feedback") from exc
    if current.shape != (9,) or not np.isfinite(current).all():
        raise ValueError("public LIBERO joint_position must be a finite 9-vector")
    target = current[:7].copy()
    # Change one axis by 0.08 rad, with direction varied per row and a strict
    # 0.15 rad displacement cap.  The bounded magnitude keeps this a diagnostic
    # trajectory; it is not a task-success or collision-avoidance planner.
    axis = row_index
    direction = 1.0 if row_index in (0, 2) else -1.0
    target[axis] += direction * 0.08
    planner = JointPositionPlanner(JointPositionPlannerConfig(
        max_joint_delta_per_step=0.02,
        max_joint_acceleration_per_step=0.006,
        max_gripper_delta_per_step=0.08,
        max_gripper_acceleration_per_step=0.02,
        settle_steps=0,
        max_steps=64,
    ))
    actions = planner.plan_to_joint_positions(
        current_positions=current[:7], target_positions=target,
        gripper=-1.0, steps=steps, settle_steps=0,
    )
    if actions.shape != (steps, 8) or not np.isfinite(actions).all():
        raise ValueError("joint planner did not produce the frozen bounded action shape")
    if float(np.max(np.abs(actions[-1, :7] - current[:7]))) > 0.1500001:
        raise ValueError("planned arm target exceeds the per-episode 0.15 rad displacement cap")
    return actions


def selected_action_from_planner(action: np.ndarray) -> np.ndarray:
    """Convert the planner's normalized hand value to aggregate meters."""
    values = np.asarray(action, dtype=np.float64)
    if values.shape != (8,) or not np.isfinite(values).all():
        raise ValueError("planner action must be a finite 8-vector")
    result = values.copy()
    result[7] = 0.04 * (float(values[7]) + 1.0)
    if not 0.0 <= result[7] <= 0.08:
        raise ValueError("planner gripper conversion escaped the source aggregate-opening range")
    return result


__all__ = ["build_planner", "plan_episode_actions", "selected_action_from_planner"]
